import '@servicenow/sdk/global'
import { Flow, wfa, action } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Flow 1: Record Updated Trigger (tests expect Updated_1 prefix)
Flow(
    {
        $id: Now.ID['flow_label_cache_trigger_created'],
        name: 'Flow - Label Cache Trigger Created',
        description: 'Tests label cache with record updated trigger',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.updated,
        { $id: Now.ID['trigger_created'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_created_trigger'] },
            {
                log_message: `Incident: ${wfa.dataPill(params.trigger.current.number, 'string')}, Priority: ${wfa.dataPill(params.trigger.current.priority, 'string')}, Table: ${wfa.dataPill(params.trigger.table_name, 'string')}, Start: ${wfa.dataPill(params.trigger.run_start_time, 'string')}`,
                log_level: 'info',
            }
        )
    }
)

